 21	
 22	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
 23	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
 24	    private static final int SELECTOR_TIMEOUT_MS = 30000;
